              'role-switch': '[role="switch"]:not([tabindex="-1"])',
              'contenteditable': '[contenteditable]:not([tabindex="-1"])'
            };

            const colors = {
              'a': 'blue',
              'button': 'green',
              'input': 'orange',
              'select': 'red',
              'textarea': 'purple',
              'role-button': 'pink',
              'role-link': 'cyan',
